#include <iostream>

using namespace std;

/**
 * Problem: 2015-02 - Recursion and Mod
 * 
 * 解題思路：
 * 1. 給定遞迴式 f(n) = 3*f(n-1) + 4, f(1) = 1。
 * 2. 觀察數列：
 *    f(1) = 1
 *    f(2) = 3(1) + 4 = 7
 *    f(3) = 3(7) + 4 = 25
 *    f(4) = 3(25) + 4 = 79
 * 3. 嘗試找通項公式：
 *    f(n) + 2 = 3(f(n-1) + 2)
 *    令 g(n) = f(n) + 2，則 g(n) = 3 * g(n-1)，g(1) = 1 + 2 = 3。
 *    因此 g(n) = 3^n，推得 f(n) = 3^n - 2。
 * 4. 題目要求 f(n) mod (10^9 + 9)。
 * 5. 使用快速冪 (Modular Exponentiation) 計算 3^n mod (10^9 + 9)。
 * 6. 注意處理減法後的負數：(3^n - 2 + MOD) % MOD。
 */

typedef long long ll;
const ll MOD = 1e9 + 9;

ll power(ll base, ll exp) {
    ll res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

int main() {
    ll n;
    while (cin >> n) {
        ll ans = (power(3, n) - 2 + MOD) % MOD;
        cout << ans << endl;
    }
    return 0;
}
